"""Build a fully local static site; only publish the explicit file set below."""
from pathlib import Path
import html,json,shutil
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'_site'
if OUT.resolve()!=ROOT.resolve()/'_site' or OUT.is_symlink(): raise SystemExit('Unsafe output directory')
if OUT.exists():
    if not (OUT/'.generated-by-3d-assets').is_file(): raise SystemExit('Refusing to replace unrecognized _site folder')
    shutil.rmtree(OUT)
OUT.mkdir(); (OUT/'.generated-by-3d-assets').write_text('Generated by tools/build_site.py\n')
files=['index.json','index.csv','selection.json','INDEX.md','ATTRIBUTIONS.md','COVERAGE.md','coverage.json','validation.json','LICENSE.md','THIRD_PARTY_NOTICES.md']
for name in files: shutil.copy2(ROOT/name,OUT/name)
for name in ['models','indices','gallery','LICENSES','kits']:
    shutil.copytree(ROOT/name,OUT/name,ignore=shutil.ignore_patterns('DESIGN.md','qa*','screenshots','*.log'))
source=OUT/'sources';source.mkdir()
for name in ['documents.json','license-coverage.json','cc-by-3.0.html','cc0-1.0.html','poly-pizza-api.SKILL.md','api-v1.1.html','terms.html']:
    shutil.copy2(ROOT/'sources'/name,source/name)
if (ROOT/'sources/external').is_dir(): shutil.copytree(ROOT/'sources/external',source/'external')
page=(ROOT/'gallery.html').read_text(encoding='utf-8-sig').replace('href="ATTRIBUTIONS.md"','href="credits.html"').replace('href="COVERAGE.md"','href="coverage.html"').replace('href="kits/index.json"','href="kits.html"')
for name in ['index.html','gallery.html']: (OUT/name).write_text(page,encoding='utf-8')
(OUT/'.nojekyll').touch()
models=json.loads((ROOT/'index.json').read_text(encoding='utf-8'))['models']
def document(title,body):
    return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' · GuateGeeks</title><link rel="stylesheet" href="gallery/style.css"><link rel="stylesheet" href="gallery/docs.css"></head><body><main class="document"><a href="./">Volver a la galería</a><h1>'+html.escape(title)+'</h1>'+body+'</main></body></html>'
credits='<p>Modelos de Poly Pizza, Kenney y OpenGameArt. Cada recurso conserva su licencia y atribución. Los derivados documentan sus cambios y archivos fuente.</p>'
for m in models:
    credits+='<article id="'+html.escape(m['id'],quote=True)+'"><h2>'+html.escape(m['title'])+'</h2><p>'+html.escape(m['attribution'])+'</p><p>'+html.escape(m['modifications'])+'</p><p><a href="'+html.escape(m['license']['url'],quote=True)+'">'+html.escape(m['licenseRaw'])+'</a> · <a href="'+html.escape(m['sourceUrl'],quote=True)+'">Fuente original</a> · <a href="'+html.escape(m['file'],quote=True)+'" download>GLB</a></p></article>'
(OUT/'credits.html').write_text(document('Licencias y créditos',credits),encoding='utf-8')
body='<p>La selección y su evaluación de uso permanecen abiertas a revisión docente.</p><pre>'+html.escape((ROOT/'COVERAGE.md').read_text(encoding='utf-8'))+'</pre>'
(OUT/'coverage.html').write_text(document('Cobertura de la biblioteca',body),encoding='utf-8')
(OUT/'gallery/docs.css').write_text('.document{max-width:80ch;margin:40px auto;padding:0 24px 60px;font-size:14px;line-height:1.8}.document h1{margin-top:30px}.document h2{font-size:17px}.document article{padding:20px 0;border-top:1px solid var(--line)}.document p,.document pre{overflow-wrap:anywhere;white-space:pre-wrap}.document pre{font:inherit;font-size:12px}',encoding='utf-8')
if (ROOT/'kits/index.json').is_file():
    kit_index=json.loads((ROOT/'kits/index.json').read_text(encoding='utf-8'))
    body='<p>Descargas completas originales, con todos los formatos incluidos por el autor. Los duplicados binarios comparten ficha; las variantes se pueden explorar individualmente en la galería.</p>'
    for kit in kit_index['kits']:
        body+='<article><h2>'+html.escape(kit['title'])+'</h2><p>'+html.escape(kit['author'])+' · '+html.escape(kit['licenseRaw'])+' · '+str(round(kit['bytes']/1024**2,1))+' MiB</p><p><a download href="'+html.escape(kit['file'],quote=True)+'">Descargar kit completo</a> · <a href="'+html.escape(kit['licenseFile'],quote=True)+'">Licencia conservada</a> · <a href="kits/'+html.escape(kit['id'],quote=True)+'/inventory.json">Inventario y hashes</a> · <a href="'+html.escape(kit['sourceUrl'],quote=True)+'">Fuente del autor</a></p><p>'+html.escape(kit['attribution'])+'</p><p>SHA-256: '+html.escape(kit['sha256'])+'</p><p><a href="gallery.html#kit='+html.escape(kit['id'],quote=True)+'">Ver kit en la galería</a></p><details><summary>Ver '+str(kit.get('logicalModels',0))+(' modelo' if kit.get('logicalModels')==1 else ' modelos')+' del kit</summary><ul>'
        for item in kit.get('assets',[]):
            body+='<li><a href="gallery.html#model='+html.escape(item['modelId'],quote=True)+'&amp;kit='+html.escape(kit['id'],quote=True)+'">'+html.escape(item['sourceName'])+'</a></li>'
        body+='</ul></details></article>'
    (OUT/'kits.html').write_text(document('Kits completos y modelos',body),encoding='utf-8')
size=sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file())
if size>=1024**3: raise SystemExit('Site exceeds GitHub Pages 1 GiB limit')
print(json.dumps({'output':'_site','models':len(models),'bytes':size,'MiB':round(size/1024**2,1)}))
